import { useState } from "react";

export const Counter = () => {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p>Нажатий: {count}</p>
      <button onClick={() => setCount((prev) => prev + 1)}>
        Увеличить
      </button>
    </div>
  );
};

