const express = require("express");
const app = express();

app.use(express.json());

const tasks = [];

app.get("/tasks", (req, res) => {
  res.json(tasks);
});

app.post("/tasks", (req, res) => {
  const title = req.body?.title;

  if (typeof title !== "string" || !title.trim()) {
    return res.status(400).json({ error: "Введите название задачи" });
  }

  const task = { id: tasks.length + 1, title: title.trim() };
  tasks.push(task);
  return res.status(201).json(task);
});

app.listen(3000, () => console.log("http://localhost:3000"));

// price.js
export function calculatePrice(price, discount) {
  if (price < 0 || discount < 0 || discount > 100) {
    throw new RangeError("Некорректная цена или скидка");
  }

  return price * (1 - discount / 100);
}

// price.test.js
import { describe, expect, it } from "vitest";
import { calculatePrice } from "./price.js";

describe("calculatePrice", () => {
  it("применяет скидку", () => {
    expect(calculatePrice(1000, 20)).toBe(800);
  });

  it("оставляет цену при нулевой скидке", () => {
    expect(calculatePrice(1000, 0)).toBe(1000);
  });

  it("отклоняет скидку больше 100%", () => {
    expect(() => calculatePrice(1000, 150)).toThrow(RangeError);
  });
});
